            class xs {
                static CreateBezierPoints(t, e = 120) {
                    let i = [];
                    for (let n = 0; n < e; n++) {
                        let s = this.MultiPointBezier(t, n / e);
                        i.push(s)
                    }
                    return i
                }
                static MultiPointBezier(t, e) {
                    let i = t.length,
                    n = 0,
                    s = 0;
                    for (let a = 0; a < i; a++) {
                        let o = t[a];
                        n += o.x * Math.pow(1 - e, i - 1 - a) * Math.pow(e, a) * this.erxiangshi(i - 1, a),
                        s += o.y * Math.pow(1 - e, i - 1 - a) * Math.pow(e, a) * this.erxiangshi(i - 1, a)
                    }
                    return new Laya.Point(n, s)
                }
                static erxiangshi(t, e) {
                    let i = 1,
                    n = 1;
                    for (; e > 0;)
                        i *= t,
                        n *= e,
                        t--,
                        e--;
                    return i / n
                }
            }
            class Ds {
                static range(t, e) {
                    return Math.random() * (e - t) + t
                }
                static rangeInt(t, e) {
                    return Math.floor(Math.random() * (e - t + 1) + t)
                }
                static limit(t, e) {
                    t = Math.min(t, e);
                    var i = (e = Math.max(t, e)) - t;
                    return t + Math.random() * i
                }
                static limitInteger(t, e) {
                    return Math.round(this.limit(t, e))
                }
                static randomArray(t) {
                    return t[Math.floor(Math.random() * t.length)]
                }
                static randrange(t, e, i = 1) {
                    if (0 == i)
                        throw new Error("step 不能为 0");
                    var n = e - t;
                    if (0 == n)
                        throw new Error("没有可用的范围(" + t + "," + e + ")");
                    n < 0 && (n = t - e);
                    var s = Math.floor((n + i - 1) / i);
                    return Math.floor(Math.random() * s) * i + Math.min(t, e)
                }
                static randint(t, e) {
                    return t > e ? t++ : e++,
                    this.randrange(t, e)
                }
            }
            class Ls extends Laya.Sprite {
                constructor() {
                    super(),
                    this._animationName = "rollingCoin",
                    this._anims = []
                }
                play(t, e, i, n, s, a) {
                    return this._animNum = 0,
                    this._animLen = a,
                    this._animationName = t,
                    this.createAnim(e, i, n, s),
                    Laya.timer.frameLoop(1, this, this.onLoop),
                    this
                }
                createAnim(t, e, i, n) {
                    this._animNum++;
                    let s = Laya.Pool.getItemByClass("FLY_ANIMATION", Laya.Animation);
                    s.loadAtlas("res/atlas/effect/" + this._animationName + ".atlas"),
                    s.interval = 25;
                    let a = .15 * Math.random() + .8;
                    s.pivot(30, 30).pos(t + Ds.rangeInt(5, 10), e + Ds.rangeInt(5, 10)).scale(a, a),
                    s.play(0, !0),
                    s.alpha = 1;
                    let o = t + Math.random() * (i - t),
                    r = e + Math.random() * (n - e),
                    l = [];
                    l.push(new Laya.Point(s.x, s.y)),
                    l.push(new Laya.Point(o, r)),
                    l.push(new Laya.Point(i, n));
                    let h = xs.CreateBezierPoints(l, Ds.rangeInt(50, 70));
                    h.push(new Laya.Point(i, n)),
                    s.path = h,
                    s.pathLength = h.length - 1,
                    s.pathIndex = 0,
                    this.addChild(s),
                    this._anims.push(s),
                    this._animNum < this._animLen && Laya.timer.frameOnce(Ds.rangeInt(4, 12), this, this.createAnim, [t, e, i, n])
                }
                onLoop() {
                    let t = this._anims.length;
                    for (let e = 0; e < t; e++) {
                        let i = this._anims[e],
                        n = i.pathIndex++;
                        if (n === i.pathLength)
                            this._anims.splice(e, 1),
                            this.onAnimComplete(i),
                            e--,
                            t--;
                        else {
                            let t = i.path[n];
                            i.pos(t.x, t.y)
                        }
                    }
                }
                onAnimComplete(t) {
                    Laya.Tween.to(
                        t,
                        {
                            scaleX: 1.5,
                            scaleY: 1.5
                        },
                        200,
                        Laya.Ease.backOut,
                        Laya.Handler.create(
                            this,
                            () => {
                                t && (t.stop(), t.removeSelf(), Laya.Pool.recover("FLY_ANIMATION", t)),
                                this.numChildren <= 0 && (Laya.timer.clear(this, this.onLoop), this.destroy(!0))
                            }
                        )
                    )
                }
            }
