                var __modGMState = {
                    inputText: "",
                    lines:[]
                };
                var __modGMLabel = null;
                function gmPrint(msg, status) {
                    var prefix = "[信息] ";
                    if (status === true)
                        prefix = "[成功] ";
                    else
                        if (status === false)
                            prefix = "[失败] ";
                    __modGMState.lines.push(prefix + String(msg));
                    if (__modGMState.lines.length > 200)
                        __modGMState.lines.shift();
                    if (__modGMLabel) {
                        __modGMLabel.text = __modGMState.lines.join("\n");
                        var lineCount = __modGMState.lines.length;
                        __modGMLabel.height = Math.max(__modGMLabel.__baseH, lineCount * 22 + 20);
                        try {
                            if (__modGMLabel.parent)
                                __modGMLabel.parent.refresh()
                        } catch (e) {}
                        try {
                            if (__modGMLabel.__scrollBar) {
                                var max = __modGMLabel.__scrollBar.max;
                                __modGMLabel.__scrollBar.setScroll(max, max, 0)
                            }
                        } catch (e) {}
                    }
                }
                function gmExecute(line) {
                    try {
                        var inst = window.__modGMUI_Instance;
                        if (!inst || inst.destroyed === true) {
                            inst = new Js();
                            window.__modGMUI_Instance = inst
                        }
                        inst.iptGm.text = line;
                        inst.onOK();
                        return true
                    } catch (e) {
                        return "执行异常: " + e
                    }
                }
